var n=`1393-barramundi-with-lemon`;var t=`world-1393`;var a=`AU`;var s=`oceania`;var r=4;var o=42;var d={en:`Barramundi with Lemon`,ua:`Баррамунді з лимоном`};var l={en:`Barramundi with Lemon is a dish from Australia featuring barramundi, lemon juice, garlic, parsley. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Баррамунді з лимоном, страва кухні країни Австралія з такими основними складниками: баррамунді, лимонний сік, часник, петрушка. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 20 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 20 хвилин.`,t:[`marinating`],m:20,i:[[`barramundi`,850,`g`],[`lemon-juice`,75,`ml`],[`olive-oil`,50,`ml`],[`garlic`,4,`clove`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 16 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 16 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:16,i:[[`unsalted-butter`,55,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,4,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,25,`g`],[`lemon`,1,`pcs`]]}];var m={slug:n,id:t,country:`AU`,region:s,servings:4,minutes:42,title:d,text:l,steps:u};export{a as country,m as default,t as id,o as minutes,s as region,r as servings,n as slug,u as steps,l as text,d as title};